// @astral-mcp/tools — runtime bridge generated by Projection
// from the toolboxes delete, fs, github. Do not edit.
//
// Sandbox-host contract:
//   Before authored code runs, the sandbox host MUST inject:
//     globalThis.__projection_toolcall = (name, args) => <host-defined>
//   `name` is the catalogued tool name, `args` a plain JSON-serializable
//   object (the bridge substitutes {} when called without arguments).
//   This module performs no I/O itself; the injected hook is the only
//   channel out of the sandbox (S1), and its return value is handed back
//   verbatim to the caller — the library-supplied `toolCall` action.

function bindTool(name) {
  return function (args) {
    const hook = globalThis["__projection_toolcall"];
    if (typeof hook !== 'function') {
      throw new Error(
        'Projection tools bridge: missing host hook globalThis.__projection_toolcall. ' +
          'The sandbox host must inject it before authored code runs.',
      );
    }
    return hook(name, args === undefined ? {} : args);
  };
}

const tools = Object.create(null);
tools["delete"] = Object.create(null);
tools["delete"]["purge"] = bindTool("delete.purge");
Object.freeze(tools["delete"]);
tools["fs"] = Object.create(null);
tools["fs"]["read_file"] = bindTool("fs.read_file");
tools["fs"]["write_file"] = bindTool("fs.write_file");
tools["fs"]["github.delete_repo"] = bindTool("fs.github.delete_repo");
Object.freeze(tools["fs"]);
tools["github"] = Object.create(null);
tools["github"]["write_file"] = bindTool("github.write_file");
tools["github"]["issue_write"] = bindTool("github.issue_write");
tools["github"]["create-ticket!"] = bindTool("github.create-ticket!");
Object.freeze(tools["github"]);
Object.freeze(tools);

export { tools };
export default tools;
